public final class CoreCommands implements CommandExecutor, TabCompleter, Listener {
 private final FlovexCore plugin; private final Storage db; private final Marketplace market;
 private final Map<UUID,Request> requests=new ConcurrentHashMap<>(); private final Map<UUID,UUID> replies=new ConcurrentHashMap<>();
 private final Map<UUID,UUID> duels=new ConcurrentHashMap<>(); private final Set<UUID> duelQueue=ConcurrentHashMap.newKeySet();
 private final Set<UUID> ffa=ConcurrentHashMap.newKeySet(); private final Map<UUID,Long> lastChat=new ConcurrentHashMap<>();
 private boolean chatMuted=false;
 private record Request(UUID sender,boolean here,long created){}
 public CoreCommands(FlovexCore p){plugin=p;db=p.getStorage();market=p.getMarket();}
 private String color(String s){return ChatColor.translateAlternateColorCodes('&',s.replaceAll("(?i)&#([0-9a-f]{6})","§x§$1"));}
 private void msg(CommandSender s,String m){s.sendMessage(color(plugin.getConfig().getString("prefix","&bFlovex &8» ")+m));}
 private boolean staff(CommandSender s){return s.hasPermission("flovexcore.staff")||s.hasPermission("flovexcore.admin");}
 private Player target(String n){return Bukkit.getPlayerExact(n);}
 private boolean player(CommandSender s){if(s instanceof Player)return true;msg(s,"&cPlayers only.");return false;}
 private String id(Player p){return p.getUniqueId().toString();}
 private void openMarket(Player p){if(plugin.getPlatform().isBedrock(p)){Inventory inv=Bukkit.createInventory(null,54,ChatColor.DARK_GRAY+"Flovex Auction House");int slot=0;for(var a:market.listings()){try{byte[] bytes=(byte[])a.get("item");ItemStack item=decode(bytes);ItemMeta meta=item.getItemMeta();List<String> lore=meta.hasLore()?new ArrayList<>(meta.getLore()):new ArrayList<>();lore.add("§7Listing: §f#"+a.get("id"));lore.add("§7Price: §a$"+a.get("price"));lore.add("§eClick to buy");meta.setLore(lore);item.setItemMeta(meta);inv.setItem(slot++,item);}catch(Exception ignored){}}p.openInventory(inv);}else plugin.getMenus().show(p,"Flovex Auction House","Browse with /ah.\nList an item: /ah sell <price>\nCollect purchases: /ah claim\nSearch: /ah search <text>");}
 private byte[] encode(ItemStack item)throws Exception{java.io.ByteArrayOutputStream b=new java.io.ByteArrayOutputStream();try(org.bukkit.util.io.BukkitObjectOutputStream o=new org.bukkit.util.io.BukkitObjectOutputStream(b)){o.writeObject(item);}return b.toByteArray();}
 private ItemStack decode(byte[] bytes)throws Exception{try(org.bukkit.util.io.BukkitObjectInputStream in=new org.bukkit.util.io.BukkitObjectInputStream(new java.io.ByteArrayInputStream(bytes))){return (ItemStack)in.readObject();}}
 private void request(Player from,Player to,boolean here){if(from.equals(to)){msg(from,"&cYou cannot request yourself.");return;}String pref=here?"tpahereauto":"tpauto";if(Boolean.parseBoolean(db.preference(to.getUniqueId(),pref,"false"))){if(here)from.sendMessage("§a"+to.getName()+" automatically accepts TPAHere.");else from.sendMessage("§a"+to.getName()+" automatically accepts TPA.");teleport(here?to:from,here?from:to);return;}requests.put(to.getUniqueId(),new Request(from.getUniqueId(),here,System.currentTimeMillis()));msg(from,"&aRequest sent to &f"+to.getName()+"&a.");msg(to,"&b"+from.getName()+" &fwants to "+(here?"teleport you to them":"teleport to you")+". &a/tpaccept &7or &c/tpadeny");}
 private void teleport(Player a,Player b){if(!a.isOnline()||!b.isOnline())return;int delay=plugin.getConfig().getInt("teleport.delay-seconds",3);Location start=a.getLocation().clone();msg(a,"&eTeleporting in "+delay+" seconds. Do not move.");Bukkit.getScheduler().runTaskLater(plugin,()->{if(!a.isOnline()||!b.isOnline())return;if(plugin.getConfig().getBoolean("teleport.cancel-on-move",true)&&a.getLocation().distanceSquared(start)>.2){msg(a,"&cTeleport cancelled because you moved.");return;}a.teleportAsync(b.getLocation());msg(a,"&aTeleported.");},delay*20L);}
 private int homeLimit(Player p){if(p.hasPermission("flovexcore.homes.unlimited"))return 999;int limit=plugin.getConfig().getInt("homes.default-limit",5);for(String key:plugin.getConfig().getConfigurationSection("homes.limits").getKeys(false))if(p.hasPermission(key))limit=Math.max(limit,plugin.getConfig().getInt("homes.limits."+key));return limit;}
 private void setHome(Player p,String name){try{int count=db.rows("SELECT id FROM homes WHERE owner=?",id(p)).size();boolean exists=!db.rows("SELECT id FROM homes WHERE owner=? AND name=?",id(p),name).isEmpty();if(!exists&&count>=homeLimit(p)){msg(p,"&cYou reached your home limit ("+homeLimit(p)+").");return;}Location l=p.getLocation();db.update("INSERT INTO homes(owner,name,world,x,y,z,yaw,pitch) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(owner,name) DO UPDATE SET world=excluded.world,x=excluded.x,y=excluded.y,z=excluded.z,yaw=excluded.yaw,pitch=excluded.pitch",id(p),name,l.getWorld().getName(),l.getX(),l.getY(),l.getZ(),l.getYaw(),l.getPitch());msg(p,"&aHome &f"+name+" &asaved.");}catch(Exception e){msg(p,"&cCould not save home.");}}
 private void goHome(Player p,String name){try{var rows=db.rows("SELECT * FROM homes WHERE owner=? AND name=?",id(p),name);if(rows.isEmpty()){msg(p,"&cHome not found.");return;}var r=rows.getFirst();World w=Bukkit.getWorld((String)r.get("world"));if(w==null){msg(p,"&cThat home world is unavailable.");return;}Location l=new Location(w,((Number)r.get("x")).doubleValue(),((Number)r.get("y")).doubleValue(),((Number)r.get("z")).doubleValue(),((Number)r.get("yaw")).floatValue(),((Number)r.get("pitch")).floatValue());p.teleportAsync(l);msg(p,"&aTeleported home.");}catch(Exception e){msg(p,"&cCould not load home.");}}
 private void listHomes(Player p){try{var rows=db.rows("SELECT name,world,x,y,z FROM homes WHERE owner=? ORDER BY name",id(p));if(rows.isEmpty()){msg(p,"&7You have no homes. Use /sethome <name>.");return;}msg(p,"&bYour homes:");for(var r:rows)msg(p,"&f"+r.get("name")+" &7("+r.get("world")+" "+(int)((Number)r.get("x")).doubleValue()+", "+(int)((Number)r.get("y")).doubleValue()+", "+(int)((Number)r.get("z")).doubleValue()+")");}catch(Exception ignored){}}
 private void rtp(Player p){if(!plugin.getConfig().getBoolean("rtp.enabled",true)){msg(p,"&cRTP is disabled.");return;}World w=Bukkit.getWorld(plugin.getConfig().getString("rtp.world","world"));if(w==null){msg(p,"&cRTP world is unavailable.");return;}int min=plugin.getConfig().getInt("rtp.min-radius",1500),max=plugin.getConfig().getInt("rtp.max-radius",10000);Random random=new Random();for(int i=0;i<plugin.getConfig().getInt("rtp.attempts",32);i++){int x=(random.nextBoolean()?1:-1)*(min+random.nextInt(Math.max(1,max-min+1)));int z=(random.nextBoolean()?1:-1)*(min+random.nextInt(Math.max(1,max-min+1)));int y=w.getHighestBlockYAt(x,z)+1;Location l=new Location(w,x+.5,y,z+.5);Material floor=l.clone().subtract(0,1,0).getBlock().getType();if(l.getBlock().isPassable()&&l.clone().add(0,1,0).getBlock().isPassable()&&floor.isSolid()&&floor!=Material.LAVA&&floor!=Material.WATER){p.teleportAsync(l);msg(p,"&aRandom teleport found.");return;}}msg(p,"&cCould not find a safe location. Try again.");}
 @Override public boolean onCommand(CommandSender s,Command c,String label,String[] a){String cmd=c.getName().toLowerCase(Locale.ROOT);Player p=s instanceof Player?(Player)s:null;
 switch(cmd){
 case "menu"->{if(!player(s))return true;plugin.getMenus().show(p,"FlovexCore","Homes: /homes\nSocial: /friends, /msg\nMarketplace: /ah, /orders, /sell, /worth\nPvP: /duel, /ffa, /pvp\nUtilities: /rtp, /stats, /settings");}
 case "sethome"->{if(!player(s))return true;if(!s.hasPermission("flovexcore.homes.use")){msg(s,"&cNo permission.");return true;}setHome(p,a.length>0?a[0]:"home");}
 case "home"->{if(!player(s))return true;if(a.length==0){listHomes(p);return true;}goHome(p,a[0]);}
 case "homes"->{if(!player(s))return true;listHomes(p);}
 case "delhome"->{if(!player(s))return true;if(a.length<1){msg(s,"&cUsage: /delhome <name>");return true;}try{msg(s,db.update("DELETE FROM homes WHERE owner=? AND name=?",id(p),a[0])>0?"&aHome deleted.":"&cHome not found.");}catch(Exception ignored){}}
 case "renamehome"->{if(!player(s))return true;if(a.length<2){msg(s,"&cUsage: /renamehome <old> <new>");return true;}try{msg(s,db.update("UPDATE homes SET name=? WHERE owner=? AND name=?",a[1],id(p),a[0])>0?"&aHome renamed.":"&cHome not found.");}catch(Exception e){msg(s,"&cThat home name is already used.");}}
 case "tpa","tpahere"->{if(!player(s))return true;if(a.length<1){msg(s,"&cUsage: /"+cmd+" <player>");return true;}Player t=target(a[0]);if(t==null){msg(s,"&cPlayer not found.");return true;}request(p,t,cmd.equals("tpahere"));}
 case "tpaccept"->{if(!player(s))return true;Request r=requests.remove(p.getUniqueId());if(r==null||System.currentTimeMillis()-r.created()>plugin.getConfig().getInt("teleport.request-expiry-seconds",60)*1000L){msg(p,"&cNo pending request.");return true;}Player from=Bukkit.getPlayer(r.sender());if(from==null){msg(p,"&cRequester is offline.");return true;}if(r.here())teleport(from,p);else teleport(p,from);}
 case "tpadeny"->{if(!player(s))return true;Request r=requests.remove(p.getUniqueId());if(r==null){msg(p,"&cNo pending request.");return true;}Player from=Bukkit.getPlayer(r.sender());if(from!=null)msg(from,"&cYour teleport request was denied.");msg(p,"&7Request denied.");}
 case "tpacancel"->{if(!player(s))return true;requests.entrySet().removeIf(e->e.getValue().sender().equals(p.getUniqueId()));msg(p,"&7Your outgoing requests were cancelled.");}
 case "tpauto","tpahereauto"->{if(!player(s))return true;String key=cmd;boolean next=!Boolean.parseBoolean(db.preference(p.getUniqueId(),key,"false"));db.setPreference(p.getUniqueId(),key,String.valueOf(next));msg(p,"&a"+key+" "+(next?"enabled":"disabled")+".");}
 case "msg"->{if(a.length<2){msg(s,"&cUsage: /msg <player> <message>");return true;}if(!(s instanceof Player))return true;Player t=target(a[0]);if(t==null){msg(s,"&cPlayer not found.");return true;}if(!db.rows("SELECT target FROM social WHERE owner=? AND target=? AND kind='IGNORE'",t.getUniqueId().toString(),id(p)).isEmpty()){msg(s,"&cThat player is not accepting your messages.");return true;}String text=String.join(" ",Arrays.copyOfRange(a,1,a.length));p.sendMessage("§d[me -> "+t.getName()+"] §f"+text);t.sendMessage("§d["+p.getName()+" -> me] §f"+text);replies.put(p.getUniqueId(),t.getUniqueId());replies.put(t.getUniqueId(),p.getUniqueId());t.playSound(t.getLocation(),Sound.BLOCK_NOTE_BLOCK_BELL,1,1.2f);}
 case "reply"->{if(!player(s))return true;if(a.length<1){msg(s,"&cUsage: /reply <message>");return true;}UUID u=replies.get(p.getUniqueId());Player t=u==null?null:Bukkit.getPlayer(u);if(t==null){msg(p,"&cNo recent conversation.");return true;}String text=String.join(" ",a);p.sendMessage("§d[me -> "+t.getName()+"] §f"+text);t.sendMessage("§d["+p.getName()+" -> me] §f"+text);}
 case "pm"->{if(!player(s))return true;boolean next=!Boolean.parseBoolean(db.preference(p.getUniqueId(),"pm","true"));db.setPreference(p.getUniqueId(),"pm",String.valueOf(!next));msg(p,"&aPrivate messages "+(next?"disabled":"enabled")+".");}
 case "ignore","unignore"->{if(!player(s))return true;if(a.length<1){msg(p,"&cUsage: /"+cmd+" <player>");return true;}OfflinePlayer t=Bukkit.getOfflinePlayer(a[0]);try{if(cmd.equals("ignore")){db.update("INSERT OR IGNORE INTO social(owner,target,kind,created) VALUES(?,?,?,?)",id(p),t.getUniqueId().toString(),"IGNORE",System.currentTimeMillis());msg(p,"&aPlayer ignored.");}else{db.update("DELETE FROM social WHERE owner=? AND target=? AND kind='IGNORE'",id(p),t.getUniqueId().toString());msg(p,"&aPlayer unignored.");}}catch(Exception ignored){}}
 case "friends"->{if(!player(s))return true;if(a.length==0||a[0].equalsIgnoreCase("list")){try{msg(p,"&bFriends:");for(var r:db.rows("SELECT target FROM social WHERE owner=? AND kind='FRIEND'",id(p)))msg(p,"&f"+Bukkit.getOfflinePlayer(UUID.fromString((String)r.get("target"))).getName());}catch(Exception ignored){}return true;}if(a.length<2){msg(p,"&cUsage: /friends <add|remove> <player>");return true;}OfflinePlayer t=Bukkit.getOfflinePlayer(a[1]);try{if(a[0].equalsIgnoreCase("add")){db.update("INSERT OR IGNORE INTO social(owner,target,kind,created) VALUES(?,?,?,?)",id(p),t.getUniqueId().toString(),"FRIEND",System.currentTimeMillis());db.update("INSERT OR IGNORE INTO social(owner,target,kind,created) VALUES(?,?,?,?)",t.getUniqueId().toString(),id(p),"FRIEND",System.currentTimeMillis());msg(p,"&aFriend added.");}else{db.update("DELETE FROM social WHERE owner=? AND target=? AND kind='FRIEND'",id(p),t.getUniqueId().toString());db.update("DELETE FROM social WHERE owner=? AND target=? AND kind='FRIEND'",t.getUniqueId().toString(),id(p));msg(p,"&cFriend removed.");}}catch(Exception ignored){}}
 case "profile","stats","playtime","ping"->{OfflinePlayer t=a.length>0?Bukkit.getOfflinePlayer(a[0]):p;if(t==null){msg(s,"&cPlayer not found.");return true;}Player online=t.getPlayer();String name=t.getName()==null?"Unknown":t.getName();if(cmd.equals("ping")){msg(s,online==null?"&7"+name+" is offline.":"&b"+name+" ping: &f"+online.getPing()+"ms");}else{int kills=online==null?0:online.getStatistic(Statistic.PLAYER_KILLS),deaths=online==null?0:online.getStatistic(Statistic.DEATHS);long ticks=0;try{var r=db.rows("SELECT play_ticks FROM player_data WHERE uuid=?",t.getUniqueId().toString());if(!r.isEmpty())ticks=((Number)r.getFirst().get("play_ticks")).longValue();}catch(Exception ignored){}if(cmd.equals("playtime"))msg(s,"&b"+name+" playtime: &f"+(ticks/72000)+"h "+(ticks/1200%60)+"m");else if(cmd.equals("stats"))msg(s,"&b"+name+" &7Kills: &f"+kills+" &7Deaths: &f"+deaths+" &7Playtime: &f"+(ticks/72000)+"h");else plugin.getMenus().show(p,"Profile: "+name,"UUID: "+t.getUniqueId()+"\nKills: "+kills+"\nDeaths: "+deaths+"\nPlaytime: "+(ticks/72000)+"h");}}
 case "rtp"->{if(!player(s))return true;rtp(p);}
 case "worth"->{Material m=a.length>0?Material.matchMaterial(a[0]):p==null?null:p.getInventory().getItemInMainHand().getType();if(m==null){msg(s,"&cUsage: /worth <material>");return true;}msg(s,"&e"+m.name()+" &7worth: &a$"+plugin.worthConfig().getDouble("prices."+m.name(),0)+" &7per item.");}
 case "sell","sellhand","sellall"->{if(!player(s))return true;if(!plugin.getEconomy().available()){msg(p,"&cMarketplace economy unavailable. Install Vault and ExcellentEconomy.");return true;}double total=0;if(cmd.equals("sellhand")){ItemStack hand=p.getInventory().getItemInMainHand();total=market.sell(p,hand,plugin.worthConfig());}else{for(int i=0;i<p.getInventory().getStorageContents().length;i++){ItemStack item=p.getInventory().getItem(i);if(item!=null&&!item.getType().isAir())total+=market.sell(p,item,plugin.worthConfig());}}msg(p,total>0?"&aSold items for &f"+plugin.getEconomy().format(total):"&cNo sellable items or active buy orders found.");}
 case "auctionhouse"->{if(!player(s))return true;if(a.length==0)openMarket(p);else if(a[0].equalsIgnoreCase("sell")&&a.length>1){try{if(market.list(p,Double.parseDouble(a[1])))msg(p,"&aItem listed.");else msg(p,"&cListing failed.");}catch(Exception e){msg(p,"&cInvalid price.");}}else if(a[0].equalsIgnoreCase("claim"))msg(p,"&aClaimed "+market.claim(p)+" item(s).");else if(a[0].equalsIgnoreCase("search")){openMarket(p);msg(p,"&7Use the current listings menu; text search is coming in the next market pass.");}}
 case "orders"->{if(!player(s))return true;if(a.length>=4&&a[0].equalsIgnoreCase("create")){Material m=Material.matchMaterial(a[1]);try{if(market.createOrder(p,m,Integer.parseInt(a[2]),Double.parseDouble(a[3])))msg(p,"&aBuy order created and funds reserved.");else msg(p,"&cCould not create order.");}catch(Exception e){msg(p,"&cUsage: /orders create <material> <amount> <unit-price>");}}else{try{msg(p,"&bActive buy orders:");for(var r:db.rows("SELECT id,material,remaining,unit_price FROM orders WHERE remaining>0 AND expires>? ORDER BY unit_price DESC",System.currentTimeMillis()))msg(p,"&f#"+r.get("id")+" "+r.get("material")+" x"+r.get("remaining")+" &a$"+r.get("unit_price"));}catch(Exception ignored){}msg(p,"&7Create: /orders create <material> <amount> <unit-price>");}}
 case "settings"->{if(!player(s))return true;plugin.getMenus().show(p,"Player Settings","Scoreboard: /scoreboard\nTPA auto: /tpauto\nTPAHere auto: /tpahereauto\nPrivate messages: /pm\nIgnore: /ignore <player>");}
 case "scoreboard"->{if(!player(s))return true;plugin.getScoreboard().toggle(p);msg(p,"&aScoreboard preference updated.");}
 case "leaderboard"->{String stat=a.length>0?a[0]:"playtime";try{if(stat.equalsIgnoreCase("playtime")){msg(s,"&bTop playtime:");for(var r:db.rows("SELECT last_name,play_ticks FROM player_data ORDER BY play_ticks DESC LIMIT 10"))msg(s,"&f"+r.get("last_name")+" &7- &e"+(((Number)r.get("play_ticks")).longValue()/72000)+"h");}else{msg(s,"&cSupported leaderboard: playtime.");}}catch(Exception ignored){}}
 case "report"->{if(!player(s))return true;if(a.length<2){msg(p,"&cUsage: /report <player> <reason>");return true;}try{db.update("INSERT INTO reports(reporter,target,reason,created) VALUES(?,?,?,?)",id(p),Bukkit.getOfflinePlayer(a[0]).getUniqueId().toString(),String.join(" ",Arrays.copyOfRange(a,1,a.length)),System.currentTimeMillis());msg(p,"&aReport submitted.");for(Player online:Bukkit.getOnlinePlayers())if(online.hasPermission("flovexcore.staff"))msg(online,"&cNew report filed by "+p.getName()+".");}catch(Exception ignored){}}
 case "bounty"->{if(a.length==0){try{msg(s,"&6Active bounties:");for(var r:db.rows("SELECT id,target,description FROM bounties WHERE active=1 ORDER BY created DESC LIMIT 20"))msg(s,"&f#"+r.get("id")+" "+Bukkit.getOfflinePlayer(UUID.fromString((String)r.get("target"))).getName()+" &7- "+r.get("description"));}catch(Exception ignored){}msg(s,"&7Create a non-monetary notice: /bounty add <player> <description>");}else if(a[0].equalsIgnoreCase("add")&&a.length>2&&staff(s)){try{db.update("INSERT INTO bounties(target,creator,description,created) VALUES(?,?,?,?)",Bukkit.getOfflinePlayer(a[1]).getUniqueId().toString(),p==null?"CONSOLE":id(p),String.join(" ",Arrays.copyOfRange(a,2,a.length)),System.currentTimeMillis());msg(s,"&aBounty notice created (no currency is used).");}catch(Exception ignored){}}}
 case "chat"->{if(!staff(s)){msg(s,"&cNo permission.");return true;}if(a.length==0||a[0].equalsIgnoreCase("status"))msg(s,"&7Chat muted: "+chatMuted);else if(a[0].equalsIgnoreCase("mute")){chatMuted=true;msg(s,"&cChat muted.");}else if(a[0].equalsIgnoreCase("unmute")){chatMuted=false;msg(s,"&aChat unmuted.");}else if(a[0].equalsIgnoreCase("clear")){for(int i=0;i<100;i++)Bukkit.broadcastMessage(" ");Bukkit.broadcastMessage("§bChat cleared by "+s.getName());}}
 case "punishments"->{if(!staff(s)){msg(s,"&cNo permission.");return true;}if(a.length<1){msg(s,"&cUsage: /punishments <player>");return true;}try{UUID u=Bukkit.getOfflinePlayer(a[0]).getUniqueId();for(var r:db.rows("SELECT type,reason,staff,created,expires FROM punishments WHERE target=? ORDER BY created DESC LIMIT 20",u.toString()))msg(s,"&c"+r.get("type")+" &7"+r.get("reason")+" &8by "+r.get("staff"));}catch(Exception ignored){}}
 case "warn","kick","ban","tempban","unban","mute","tempmute","unmute"->{if(!staff(s)){msg(s,"&cNo permission.");return true;}if(a.length<1){msg(s,"&cUsage: /"+cmd+" <player> [reason]");return true;}OfflinePlayer off=Bukkit.getOfflinePlayer(a[0]);String reason=a.length>1?String.join(" ",Arrays.copyOfRange(a,1,a.length)):"No reason provided";Player online=off.getPlayer();long expiry=(cmd.equals("tempban")?plugin.getConfig().getLong("moderation.tempban-default-seconds",86400):cmd.equals("tempmute")?plugin.getConfig().getLong("moderation.tempmute-default-seconds",3600):0);try{if(cmd.equals("unban")||cmd.equals("unmute")){db.update("UPDATE punishments SET active=0 WHERE target=? AND type=?",off.getUniqueId().toString(),cmd.equals("unban")?"BAN":"MUTE");msg(s,"&aPunishment cleared.");}else{String type=cmd.equals("tempban")||cmd.equals("ban")?"BAN":cmd.equals("tempmute")||cmd.equals("mute")?"MUTE":cmd.toUpperCase(Locale.ROOT);db.update("INSERT INTO punishments(target,staff,type,reason,expires,created) VALUES(?,?,?,?,?,?)",off.getUniqueId().toString(),s.getName(),type,reason,expiry==0?0:System.currentTimeMillis()+expiry*1000,System.currentTimeMillis());if(online!=null&&(type.equals("BAN")||cmd.equals("kick")))online.kickPlayer(reason);msg(s,"&a"+cmd+" applied to "+a[0]+".");}}catch(Exception e){msg(s,"&cCould not update punishment.");}}
 case "freeze"->{if(!staff(s)){msg(s,"&cNo permission.");return true;}if(a.length<1){msg(s,"&cUsage: /freeze <player>");return true;}Player t=target(a[0]);if(t==null){msg(s,"&cPlayer not found.");return true;}boolean v=!Boolean.parseBoolean(db.preference(t.getUniqueId(),"frozen","false"));db.setPreference(t.getUniqueId(),"frozen",String.valueOf(v));msg(s,"&a"+t.getName()+" frozen="+v);}
 case "stafflist"->{msg(s,"&bOnline staff:");for(Player t:Bukkit.getOnlinePlayers())if(staff(t))msg(s,"&f"+t.getName());}
 case "staffchat"->{if(!staff(s))return true;if(a.length==0){msg(s,"&cUsage: /staffchat <message>");return true;}String text="§c[Staff] §f"+s.getName()+": "+String.join(" ",a);for(Player t:Bukkit.getOnlinePlayers())if(staff(t))t.sendMessage(text);}
 case "helpop"->{if(a.length==0){msg(s,"&cUsage: /helpop <message>");return true;}for(Player t:Bukkit.getOnlinePlayers())if(staff(t))t.sendMessage("§c[HelpOp] §f"+s.getName()+": "+String.join(" ",a));msg(s,"&aMessage sent to online staff.");}
 case "staffmode"->{if(!player(s))return true;if(!p.hasPermission("flovexcore.staffmode"))return true;boolean v=!Boolean.parseBoolean(db.preference(p.getUniqueId(),"staffmode","false"));db.setPreference(p.getUniqueId(),"staffmode",String.valueOf(v));msg(p,"&aStaff mode "+(v?"enabled":"disabled")+".");}
 case "fly"->{if(!player(s))return true;if(!staff(p))return true;p.setAllowFlight(!p.getAllowFlight());p.setFlying(p.getAllowFlight());msg(p,"&aFlight "+(p.getAllowFlight()?"enabled":"disabled")+".");}
 case "flyspeed"->{if(!player(s))return true;if(!staff(p))return true;try{float speed=Math.max(.1f,Math.min(1f,Float.parseFloat(a[0])));p.setFlySpeed(speed);msg(p,"&aFly speed set.");}catch(Exception e){msg(p,"&cUsage: /flyspeed <0.1-1.0>");}}
 case "heal","feed"->{Player t=a.length>0?target(a[0]):p;if(t==null){msg(s,"&cPlayer not found.");return true;}if(!staff(s))return true;if(cmd.equals("heal")){t.setHealth(Objects.requireNonNull(t.getAttribute(Attribute.MAX_HEALTH)).getValue());t.setFireTicks(0);}else t.setFoodLevel(20);msg(s,"&a"+cmd+" applied.");}
 case "gamemode"->{if(!staff(s)||a.length<1)return true;Player t=a.length>1?target(a[1]):p;try{t.setGameMode(GameMode.valueOf(a[0].toUpperCase(Locale.ROOT)));msg(s,"&aGamemode updated.");}catch(Exception e){msg(s,"&cInvalid gamemode.");}}
 case "vanish"->{if(!player(s)||!staff(p))return true;boolean v=!Boolean.parseBoolean(db.preference(p.getUniqueId(),"vanished","false"));db.setPreference(p.getUniqueId(),"vanished",String.valueOf(v));for(Player t:Bukkit.getOnlinePlayers())if(t!=p){if(v&&!staff(t))t.hidePlayer(plugin,p);else t.showPlayer(plugin,p);}msg(p,"&aVanish "+(v?"enabled":"disabled")+".");}
 case "invsee"->{if(!staff(s)||a.length<1)return true;Player t=target(a[0]);if(t==null){msg(s,"&cPlayer not found.");return true;}if(p!=null)p.openInventory(t.getInventory());}
 case "teleport"->{if(!staff(s)||a.length<1||!player(s))return true;Player t=target(a[0]);if(t==null){msg(s,"&cPlayer not found.");return true;}p.teleportAsync(t.getLocation());}
 case "findplayer"->{if(a.length<1){msg(s,"&cUsage: /findplayer <player>");return true;}OfflinePlayer t=Bukkit.getOfflinePlayer(a[0]);msg(s,t.isOnline()?"&a"+a[0]+" is online.":"&7"+a[0]+" is offline.");}
 case "nightvision"->{if(!player(s))return true;if(p.hasPotionEffect(PotionEffectType.NIGHT_VISION))p.removePotionEffect(PotionEffectType.NIGHT_VISION);else p.addPotionEffect(new PotionEffect(PotionEffectType.NIGHT_VISION,20*60*60,0,false,false));}
 case "god"->{if(!player(s)||!staff(p))return true;boolean v=!Boolean.parseBoolean(db.preference(p.getUniqueId(),"god","false"));db.setPreference(p.getUniqueId(),"god",String.valueOf(v));msg(p,"&aGod mode "+(v?"enabled":"disabled")+".");}
 case "duel"->{if(!player(s))return true;if(a.length<1){msg(p,"&cUsage: /duel <player>");return true;}Player t=target(a[0]);if(t==null||t==p){msg(p,"&cInvalid player.");return true;}requests.put(t.getUniqueId(),new Request(p.getUniqueId(),false,System.currentTimeMillis()));msg(p,"&aDuel challenge sent to "+t.getName()+". Target uses /duel accept.");}
 case "queue"->{if(!player(s))return true;if(duelQueue.add(p.getUniqueId()))msg(p,"&aJoined duel queue.");else{duelQueue.remove(p.getUniqueId());msg(p,"&cLeft duel queue.");}}
 case "leave"->{if(!player(s))return true;duelQueue.remove(p.getUniqueId());ffa.remove(p.getUniqueId());UUID opponent=duels.remove(p.getUniqueId());if(opponent!=null){duels.remove(opponent);Player o=Bukkit.getPlayer(opponent);if(o!=null)msg(o,"&cYour opponent left the match.");}msg(p,"&7You left the queue or match.");}
 case "draw"->{if(!player(s))return true;UUID opponent=duels.get(p.getUniqueId());Player o=opponent==null?null:Bukkit.getPlayer(opponent);if(o==null)msg(p,"&cYou are not in a duel.");else{msg(o,"&eYour opponent requests a draw. Use /draw accept.");msg(p,"&aDraw request sent.");}}
 case "arena"->{if(!staff(s)||!player(s))return true;if(a.length<1){msg(s,"&c/arena <setpos1|setpos2>");return true;}Location l=p.getLocation();String key="duels.arena."+a[0].toLowerCase(Locale.ROOT);if(a[0].equalsIgnoreCase("setpos1")||a[0].equalsIgnoreCase("setpos2")){plugin.getConfig().set(key,loc(l));plugin.saveConfig();msg(s,"&aArena "+a[0]+" saved.");}}
 case "ffa"->{if(!player(s))return true;if(!plugin.getConfig().getBoolean("pvp.ffa-enabled",true)){msg(p,"&cFFA disabled.");return true;}if(a.length>0&&a[0].equalsIgnoreCase("leave")){ffa.remove(p.getUniqueId());msg(p,"&7Left FFA.");return true;}String w=plugin.getConfig().getString("pvp.ffa-world","world");World world=Bukkit.getWorld(w);if(world==null){msg(p,"&cFFA spawn not configured.");return true;}double x=plugin.getConfig().getDouble("pvp.ffa-x",0),y=plugin.getConfig().getDouble("pvp.ffa-y",100),z=plugin.getConfig().getDouble("pvp.ffa-z",0);ffa.add(p.getUniqueId());p.teleportAsync(new Location(world,x,y,z));msg(p,"&aJoined FFA.");}
 case "ffastats"->{OfflinePlayer t=a.length>0?Bukkit.getOfflinePlayer(a[0]):p;if(t==null)return true;try{var r=db.rows("SELECT kills,deaths,rating FROM ffa_stats WHERE uuid=?",t.getUniqueId().toString());if(r.isEmpty())msg(s,"&7No FFA stats.");else msg(s,"&bFFA "+t.getName()+" &7Kills: "+r.getFirst().get("kills")+" Deaths: "+r.getFirst().get("deaths")+" Rating: "+r.getFirst().get("rating"));}catch(Exception ignored){}}
 case "ffaarena"->{if(!staff(s)||!player(s))return true;if(a.length>0&&a[0].equalsIgnoreCase("setspawn")){Location l=p.getLocation();plugin.getConfig().set("pvp.ffa-world",l.getWorld().getName());plugin.getConfig().set("pvp.ffa-x",l.getX());plugin.getConfig().set("pvp.ffa-y",l.getY());plugin.getConfig().set("pvp.ffa-z",l.getZ());plugin.saveConfig();msg(p,"&aFFA spawn saved.");}else msg(s,"&cUsage: /ffaarena setspawn");}
 case "pvp"->{if(!player(s))return true;if(a.length==0||a[0].equalsIgnoreCase("stats")){msg(p,"&bPvP stats: &7"+p.getStatistic(Statistic.PLAYER_KILLS)+" kills, "+p.getStatistic(Statistic.DEATHS)+" deaths.");}else if(a[0].equalsIgnoreCase("leave")){ffa.remove(p.getUniqueId());msg(p,"&7Left PvP.");}else if(a[0].equalsIgnoreCase("join")){msg(p,"&7Use /ffa to join the configured arena.");}}
 default->{msg(s,"&7FlovexCore command. Use /menu.");}
 }
 return true;
 }
 private String loc(Location l){return l.getWorld().getName()+","+l.getX()+","+l.getY()+","+l.getZ()+","+l.getYaw()+","+l.getPitch();}
 @EventHandler public void onJoin(PlayerJoinEvent e){Player p=e.getPlayer();try{db.update("INSERT INTO player_data(uuid,last_name,first_join,last_seen) VALUES(?,?,?,?) ON CONFLICT(uuid) DO UPDATE SET last_name=excluded.last_name,last_seen=excluded.last_seen",id(p),p.getName(),System.currentTimeMillis(),System.currentTimeMillis());}catch(Exception ignored){}if(Boolean.parseBoolean(db.preference(p.getUniqueId(),"vanished","false")))for(Player t:Bukkit.getOnlinePlayers())if(t!=p&&!staff(t))t.hidePlayer(plugin,p);plugin.getScoreboard().update(p);}
 @EventHandler public void onQuit(PlayerQuitEvent e){requests.remove(e.getPlayer().getUniqueId());}
 @EventHandler public void onMove(PlayerMoveEvent e){if(Boolean.parseBoolean(db.preference(e.getPlayer().getUniqueId(),"frozen","false"))&&e.getTo()!=null&&(e.getFrom().getBlockX()!=e.getTo().getBlockX()||e.getFrom().getBlockY()!=e.getTo().getBlockY()||e.getFrom().getBlockZ()!=e.getTo().getBlockZ()))e.setTo(e.getFrom());}
 @EventHandler public void onChat(AsyncChatEvent e){Player p=e.getPlayer();if(chatMuted&&!staff(p)){e.setCancelled(true);msg(p,"&cChat is muted.");return;}try{var mute=db.rows("SELECT id FROM punishments WHERE target=? AND type='MUTE' AND active=1 AND (expires=0 OR expires>?)",id(p),System.currentTimeMillis());if(!mute.isEmpty()){e.setCancelled(true);msg(p,"&cYou are muted.");return;}}catch(Exception ignored){}long now=System.currentTimeMillis(),last=lastChat.getOrDefault(p.getUniqueId(),0L);int delay=plugin.getConfig().getInt("chat.slowmode-seconds",0);if(delay>0&&now-last<delay*1000L&&!staff(p)){e.setCancelled(true);msg(p,"&cSlow down.");return;}lastChat.put(p.getUniqueId(),now);String plain=net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer.plainText().serialize(e.message());int max=plugin.getConfig().getInt("chat.max-length",256);if(plain.length()>max){e.setCancelled(true);msg(p,"&cMessage too long.");return;}for(Player viewer:Bukkit.getOnlinePlayers())if(!viewer.equals(p)&&!db.rows("SELECT target FROM social WHERE owner=? AND target=? AND kind='IGNORE'",viewer.getUniqueId().toString(),id(p)).isEmpty())e.viewers().remove(viewer);}
 @EventHandler public void onInventory(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p)||!e.getView().getTitle().equals(ChatColor.DARK_GRAY+"Flovex Auction House"))return;e.setCancelled(true);ItemStack item=e.getCurrentItem();if(item==null||!item.hasItemMeta()||!item.getItemMeta().hasLore())return;for(String line:item.getItemMeta().getLore())if(line.startsWith("§7Listing: §f#")){try{long id=Long.parseLong(line.substring(line.indexOf('#')+1));if(market.buy(p,id))msg(p,"&aPurchased. Use /ah claim.");else msg(p,"&cPurchase failed.");}catch(Exception ignored){}break;}}
 @EventHandler public void onDeath(PlayerDeathEvent e){Player dead=e.getEntity();UUID opponent=duels.remove(dead.getUniqueId());if(opponent!=null){duels.remove(opponent);Player winner=Bukkit.getPlayer(opponent);if(winner!=null)msg(winner,"&aYou won the duel.");}if(dead.getKiller()!=null){Player killer=dead.getKiller();try{db.update("INSERT INTO ffa_stats(uuid,kills,deaths,rating) VALUES(?,1,0,1000) ON CONFLICT(uuid) DO UPDATE SET kills=kills+1",killer.getUniqueId().toString());db.update("INSERT INTO ffa_stats(uuid,kills,deaths,rating) VALUES(?,0,1,1000) ON CONFLICT(uuid) DO UPDATE SET deaths=deaths+1",dead.getUniqueId().toString());}catch(Exception ignored){}}}
 @Override public List<String> onTabComplete(CommandSender s,Command c,String alias,String[] args){if(args.length==1)return switch(c.getName().toLowerCase(Locale.ROOT)){case "auctionhouse"->List.of("sell","claim","search");case "orders"->List.of("create","cancel","my");case "friends"->List.of("list","add","remove");case "chat"->List.of("mute","unmute","clear","status");case "duel"->List.of("accept","deny");case "arena"->List.of("setpos1","setpos2");case "ffa"->List.of("join","leave");default->Bukkit.getOnlinePlayers().stream().map(Player::getName).toList();};if(c.getName().equalsIgnoreCase("orders")&&args.length==2&&args[0].equalsIgnoreCase("create"))return Arrays.stream(Material.values()).filter(Material::isItem).map(m->m.name().toLowerCase(Locale.ROOT)).filter(n->n.startsWith(args[1].toLowerCase(Locale.ROOT))).limit(50).toList();return List.of();}
}